window.kbPageData["views/entry/k-6f0c9645422163f1"] = {"key":"entry/k-6f0c9645422163f1","state":{"route":"entry/k-6f0c9645422163f1"},"node":{"id":"k-6f0c9645422163f1","mode":"k","title":"无废工厂的源头减量与资源循环利用","type":"原理与机制","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":["无废工厂建设中的源头减量与资源循环利用"],"qs":["国考 2025 行政执法 申论#4"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"源头减量是通过改进生产工艺、调整投入材料等方式，减少废物的产生。资源循环利用是让可回用的资源再次投入使用，减少新增资源消耗。","review":{"definition":"源头减量是通过改进生产工艺、调整投入材料等方式，减少废物的产生。资源循环利用是让可回用的资源再次投入使用，减少新增资源消耗。","explanation":"申论第4题中，西瑞药业循环使用大部分生产用水，每日用水量节约一半以上，体现了资源循环利用。制瓶工艺优化后废气产生量下降，替换滤料后废活性炭减少，体现了生产源头减排减废。谈话提纲可把这些写成已取得的成效，生产用水100%回收利用和制瓶工序不产生废气则仍是拟实现的目标。","references":[],"evidence":"生产用水大部分能循环使用，每天用水量节约一半以上。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 行政执法 申论#4":{"paper":"国考 2025 行政执法 申论","n":4,"mod":"申论","src":["dbb2469ea58338709f40.pdf",4],"asrc":["d1fc3fe21ef6ae3b1ae6.pdf",3],"card":"e9b26cf35f72426e9b032d20","links":[{"id":"k-6f0c9645422163f1","role":"直接考查","why":"用水循环、工艺优化和滤料替代分别体现了资源循环利用和从生产源头减少废弃物。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-6f0c9645422163f1":[["国考 2025 行政执法 申论#4"]]}};
